'use client';

import { useRouter } from 'next/navigation';

type BackButtonProps = {
  fallbackHref?: string;
  label?: string;
};

export function BackButton({
  fallbackHref = '/blog',
  label = '← Back',
}: BackButtonProps) {
  const router = useRouter();

  const handleClick = () => {
    if (window.history.length > 1) {
      router.back();
      return;
    }

    router.push(fallbackHref);
  };

  return (
    <button type=\"button\" onClick={handleClick}>
      {label}
    </button>
  );
}
