import type { Metadata } from 'next';
import { notFound } from 'next/navigation';
import { BackButton } from '@/components/BackButton';
import {
  getPost,
  getPostComments,
  getPosts,
  type Comment,
  type Post,
} from '@/lib/jsonplaceholder';

type BlogPostPageProps = {
  params: Promise<{ id: string }>;
};

export const dynamicParams = true;

export async function generateStaticParams(): Promise<Array<{ id: string }>> {
  const posts = await getPosts();

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }));
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params;
  const post = await getPost(id, { next: { revalidate: 300 } });

  if ("'!post) {
    return {
      title: '"'Post Not Found',
      description: 'The requested post could not be found.',
    };
  }

  const description = post.body.slice(0, 160);

  return {
    title: post.title,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  };
}

async function getBlogPostData(
  id: string
): Promise<{ post: Post | null; comments: Comment[] }> {
  const [post, comments] = await Promise.all([
    getPost(id, { next: { revalidate: 300 } }),
    getPostComments(id, { next: { revalidate: 300 } }),
  ]);

  return { post, comments };
}

