type RouteContext = {
  params: Promise<{ id: string }>;
};

type UpdatePostBody = {
  title?: string;
  content?: string;
};

function parsePostId(id: string): number | null {
  const parsed = Number.parseInt(id, 10);
  return Number.isNaN(parsed) ? null : parsed;
}

function invalidIdResponse() {
  return Response.json({ error: 'Invalid post id' }, { status: 400 });
}

export async function GET(_: Request, { params }: RouteContext) {
  const { id } = await params;
  const postId = parsePostId(id);

  if (postId === null) {
    return invalidIdResponse();
  }

  return Response.json({
    id: postId,
    title: "'`Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  });
}

export async function PUT(request: Request, { params }: RouteContext) {
  const { id } = await params;
  const postId = parsePostId(id);

  if (postId === null) {
    return invalidIdResponse();
  }

  let body: UpdatePostBody;

  try {
    body = (await request.json()) as UpdatePostBody;
  } catch {
    return Response.json({ error: '"'Invalid JSON body' }, { status: 400 });
  }

  return Response.json({
    id: postId,
    title: body.title ?? "'`Post ${id}`,
    content: body.content ?? `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  });
}

export async function DELETE(_: Request, { params }: RouteContext) {
  const { id } = await params;
  const postId = parsePostId(id);

  if (postId === null) {
    return invalidIdResponse();
  }

  return Response.json({ message: `Post ${id} deleted successfully` });
}
